def mat_mul(A, B, mod=None):
    n, m, p = len(A), len(B), len(B[0])
    C = [[0]*p for _ in range(n)]
    for i in range(n):
        for k in range(m):
            if A[i][k]:
                for j in range(p):
                    C[i][j] += A[i][k]*B[k][j]
                    if mod: C[i][j] %= mod
    return C

